    {
      "name": "Streaming master",
      "how": "Style Modern (or Allround), Output Level -1.0 dB, True Peak on, Oversampling 4x, Lookahead 1–2 ms. Raise Gain until the loudest bars limit 2–4 dB. Aim for -14 to -9 LUFS integrated by genre; check with Unity Gain."
    },
    {
      "name": "Loud club or bass master",
      "how": "Style Aggressive or Modern, Gain for 4–6 dB of limiting, Lookahead 0.5–1 ms, short Release, Channel Link Transients 50–75%, Oversampling 8x. If it crackles, take a dB of Gain off, or clip before it (Saturn, a clipper) so Pro-L does less."
    },
    {
      "name": "Bus peaks",
      "how": "Style Bus or Punchy, Gain 1–3 dB, Lookahead 0–0.5 ms, Output Level -0.3 dB: only the peaks."
    },
    {
      "name": "Safety limiter",
      "how": "Style Safe or Transparent, Gain 0 dB, Output Level -1.0 dB, True Peak on: only overs get touched."
