          "about": "On creates the band, off removes it. Nothing else on the band works while it's off.",
          "live": "not among this plug-in's names (look in the grouped list)"
        },
        {
          "role": "enabled",
          "about": "Bypasses the band, keeping its settings.",
          "live": "not among this plug-in's names (look in the grouped list)"
        },
        {
          "role": "frequency",
          "about": "Hz, 10 Hz–30 kHz.",
          "live": "not among this plug-in's names (look in the grouped list)"
        },
        {
          "role": "gain",
          "about": "dB, ±30 (ignored by cuts, notches and band-pass).",
          "live": "not among this plug-in's names (look in the grouped list)"
        },
        {
          "role": "q",
          "about": "0.025–40, higher is narrower; on cuts and shelves, the corner's resonance.",
          "live": "not among this plug-in's names (look in the grouped list)"
        },
        {
          "role": "shape",
          "about": "Bell, Low Shelf, Low Cut, High Shelf, High Cut, Notch, Band Pass, Tilt Shelf, Flat Tilt (and Pro-Q 4's newer ones).",
          "live": "not among this plug-in's names (look in the grouped list)"
