          "live": "not among this plug-in's names (look in the grouped list)"
        },
        {
          "role": "stereo placement",
          "about": "Stereo, Left, Right, Mid or Side.",
          "live": "not among this plug-in's names (look in the grouped list)"
        }
      ]
    },
    {
      "name": "Dynamics and spectral",
      "about": "Per band. A dynamic band's gain moves from Gain toward Gain + Range as its level goes past Threshold.",
      "parameters": [
        {
          "role": "dynamics on",
          "about": "Makes the band dynamic.",
          "live": "not among this plug-in's names (look in the grouped list)"
        },
        {
          "role": "range",
          "about": "dB. Negative cuts when loud, positive boosts when loud. Gain 0 with Range -6: up to 6 dB off, only when it's loud.",
          "live": "not among this plug-in's names (look in the grouped list)"
