      "name": "Global",
      "about": "The whole EQ.",
      "parameters": [
        {
          "role": "processing mode",
          "about": "Zero Latency (default), Natural Phase (analog-like phase, small latency), Linear Phase (no phase shift; latency and pre-ringing, their length set by Resolution).",
          "live": "not among this plug-in's names (look in the grouped list)"
        },
        {
          "role": "character",
